package com.campusiq.auth.security; import io.jsonwebtoken.*; import io.jsonwebtoken.security.Keys; import org.springframework.beans.factory.annotation.Value; import org.springframework.stereotype.Service; import javax.crypto.SecretKey; import java.util.*; @Service public class JwtService { private final SecretKey key; private final long expirationMillis; public JwtService(@Value("${app.jwt.secret}") String secret,@Value("${app.jwt.expiration-minutes}") long minutes){key=Keys.hmacShaKeyFor(Base64.getDecoder().decode(secret));expirationMillis=minutes*60_000;} public String createToken(Long id,String email){return Jwts.builder().subject(email).claim("userId",id).issuedAt(new Date()).expiration(new Date(System.currentTimeMillis()+expirationMillis)).signWith(key).compact();} public String email(String token){return Jwts.parser().verifyWith(key).build().parseSignedClaims(token).getPayload().getSubject();} }
